import{_ as i,l,o as a,c as s,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"内核模块","description":"","frontmatter":{"title":"内核模块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-module.md","filePath":"cs/kernel-module.md","lastUpdated":1789023840000}'),h={name:"cs/kernel-module.md"};function E(m,e,u,_,f,B){const r=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="内核模块" tabindex="-1">内核模块 <a class="header-anchor" href="#内核模块" aria-label="Permalink to &quot;内核模块&quot;">​</a></h1><div class="epigraph"><p>可加载模块是在运行中链入内核地址空间的目标文件：init 注册驱动，exit 注销，符号必须与正在跑的内核匹配。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum 对可加载驱动的整理</footer></div><p><a href="/cs/tty-pty">上一课</a>的驱动不必全部编进内核镜像。<a href="/cs/user-kernel-split">用户/内核分裂</a> 里内核代码已在高半。<a href="/cs/syscall-path">系统调用</a> 不能让用户随便跳进任意内核函数。缺口是 <strong>LKM</strong>：合法的扩展路径，带版本魔数与符号解析，不是任意代码注入教程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若所有驱动静态链接，发行内核巨大，且无法在运行时接新设备。模块：<code>insmod</code>/<code>modprobe</code> 把 ELF 搬到内核虚地址，解析对 <code>EXPORT_SYMBOL</code> 的引用，调 <code>init</code>。失败则卸载。缺口：许可、依赖、以及卸载时必须无引用（设备仍打开则拒绝）。本课不写如何绕过签名强制。</p><p><span class="marginnote">vermagic 匹配内核版本与配置。签名模块在安全启动策略下由内核验签。本课只要求有匹配与验签钩子，不给伪造步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构建：针对该内核的 headers 编译。加载：系统调用把映像拷入内核，relocate，调 init（注册 tty、块、文件系统类型）。使用：此后走已有 VFS/块/中断路径。卸载：<code>exit</code> 反注册，释放 <a href="/cs/slab-allocator">slab</a> 对象。不要在 init 里失败却留下半注册状态。</p>',8)),(a(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ELF%5B%22%E6%A8%A1%E5%9D%97%20ELF%22%5D%20--%3E%20REL%5B%22%E5%86%85%E6%A0%B8%E5%86%85%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20REL%20--%3E%20INIT%5B%22init%20%E6%B3%A8%E5%86%8C%22%5D%0A%20%20INIT%20--%3E%20USE%5B%22%E8%AF%B7%E6%B1%82%E8%B5%B0%E5%8E%9F%E6%9C%89%E5%AD%90%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20EXIT%5B%22exit%22%5D%20--%3E%20UNREG%5B%22%E5%8F%8D%E6%B3%A8%E5%86%8C%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模块让宏内核在部署上可裁剪：还是同一特权地址空间，不是微内核 IPC。错误的模块能毁掉整机——这是特权的含义，不是邀请实验提权。与用户动态链接对照：<a href="/cs/load-dynlink">加载</a> 在用户页表；模块在内核页表，无用户可执行权限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 livepatch 的全部一致性模型。不把 out-of-tree 驱动的 ABI 稳定性当保证。下一课：已经加载的内核如何把状态导出成文件，供模块与用户查询——proc 与 sysfs。</p><p>后课默认：驱动可运行时链入。内核树状状态的文件接口，下一课 sysfs/proc。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模块在内核地址空间重定位并 init/exit。</li><li>vermagic 与可选签名约束匹配；本课不讲绕过。</li><li>只读导出内核状态是 sysfs/proc 的缺口。</li><li>出处：Love, <em>LKD</em>；Tanenbaum <em>MOS</em>；Linux kbuild 文档。</li></ul>',7))])}const b=i(h,[["render",E]]);export{T as __pageData,b as default};
